-- ----------------------------
-- Table structure for yg_ai_generate_task
-- ----------------------------
DROP TABLE IF EXISTS `yg_ai_generate_task`;
CREATE TABLE `yg_ai_generate_task`  (
  `task_id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '任务主键',
  `canvas_id` bigint(20) NULL DEFAULT 0 COMMENT '来源画布ID(0表示非画布发起)',
  `node_id` varchar(64) CHARACTER SET utf8 COLLATE utf8_croatian_ci NULL DEFAULT '' COMMENT '来源画布节点ID',
  `model_id` bigint(20) NOT NULL COMMENT '使用模型ID(yg_ai_model)',
  `generate_type` tinyint(2) NOT NULL COMMENT '生成类型(1:文本 2:图片 3:视频)',
  `prompt` text CHARACTER SET utf8 COLLATE utf8_croatian_ci NOT NULL COMMENT '提示词',
  `status` char(1) CHARACTER SET utf8 COLLATE utf8_croatian_ci NULL DEFAULT '0' COMMENT '状态（0排队 1生成中 2成功 3失败）',
  `result_text` mediumtext CHARACTER SET utf8 COLLATE utf8_croatian_ci NULL COMMENT '文本生成结果',
  `result_url` varchar(500) CHARACTER SET utf8 COLLATE utf8_croatian_ci NULL DEFAULT '' COMMENT '媒体结果地址(/profile/...)',
  `media_id` bigint(20) NULL DEFAULT 0 COMMENT '生成的素材ID(yg_media, 图片/视频)',
  `error_msg` varchar(1000) CHARACTER SET utf8 COLLATE utf8_croatian_ci NULL DEFAULT NULL COMMENT '失败原因',
  `create_by` varchar(64) CHARACTER SET utf8 COLLATE utf8_croatian_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`task_id`) USING BTREE,
  INDEX `idx_task_status`(`status` ASC) USING BTREE,
  INDEX `idx_task_canvas`(`canvas_id` ASC, `node_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 4 CHARACTER SET = utf8 COLLATE = utf8_croatian_ci COMMENT = 'AI生成任务表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of yg_ai_generate_task
-- ----------------------------

-- ----------------------------
-- Table structure for yg_ai_model
-- ----------------------------
DROP TABLE IF EXISTS `yg_ai_model`;
CREATE TABLE `yg_ai_model`  (
  `model_id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '模型主键',
  `model_name` varchar(100) CHARACTER SET utf8 COLLATE utf8_croatian_ci NOT NULL COMMENT '模型名称(如gpt-4o/Midjourney/Suno等)',
  `model_type` tinyint(2) NOT NULL DEFAULT 1 COMMENT '模型类型(1:文本 2:图片 3:视频 4:音乐 5:旁白 6:多模态 7:向量化)',
  `provider` varchar(100) CHARACTER SET utf8 COLLATE utf8_croatian_ci NULL DEFAULT '' COMMENT '提供方(OpenAI/Anthropic/阿里/Suno等)',
  `api_url` varchar(300) CHARACTER SET utf8 COLLATE utf8_croatian_ci NULL DEFAULT '' COMMENT 'API地址',
  `api_key` varchar(300) CHARACTER SET utf8 COLLATE utf8_croatian_ci NULL DEFAULT '' COMMENT 'API Key',
  `sort` int(4) NULL DEFAULT 0 COMMENT '显示排序',
  `status` char(1) CHARACTER SET utf8 COLLATE utf8_croatian_ci NULL DEFAULT '0' COMMENT '状态（0正常 1停用）',
  `del_flag` char(1) CHARACTER SET utf8 COLLATE utf8_croatian_ci NULL DEFAULT '0' COMMENT '删除标志（0代表存在 2代表删除）',
  `create_by` varchar(64) CHARACTER SET utf8 COLLATE utf8_croatian_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) CHARACTER SET utf8 COLLATE utf8_croatian_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(500) CHARACTER SET utf8 COLLATE utf8_croatian_ci NULL DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`model_id`) USING BTREE,
  INDEX `idx_ai_model_name`(`model_name`(64) ASC) USING BTREE,
  INDEX `idx_ai_model_type`(`model_type` ASC, `status` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 5 CHARACTER SET = utf8 COLLATE = utf8_croatian_ci COMMENT = 'AI生成模型档案表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of yg_ai_model
-- ----------------------------

-- ----------------------------
-- Table structure for yg_ai_prompt
-- ----------------------------
DROP TABLE IF EXISTS `yg_ai_prompt`;
CREATE TABLE `yg_ai_prompt`  (
  `prompt_id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '提示词主键',
  `prompt_name` varchar(200) CHARACTER SET utf8 COLLATE utf8_croatian_ci NOT NULL COMMENT '提示词标题',
  `prompt_type` tinyint(2) NOT NULL DEFAULT 1 COMMENT '生成类型(1:文本 2:图片 3:视频 4:音乐 5:旁白 6:多模态)',
  `prompt_content` text CHARACTER SET utf8 COLLATE utf8_croatian_ci NOT NULL COMMENT '提示词内容',
  `model_name` varchar(100) CHARACTER SET utf8 COLLATE utf8_croatian_ci NULL DEFAULT '' COMMENT '适用模型(如ChatGPT/Midjourney/Suno等)',
  `status` char(1) CHARACTER SET utf8 COLLATE utf8_croatian_ci NULL DEFAULT '0' COMMENT '状态（0正常 1停用）',
  `del_flag` char(1) CHARACTER SET utf8 COLLATE utf8_croatian_ci NULL DEFAULT '0' COMMENT '删除标志（0代表存在 2代表删除）',
  `create_by` varchar(64) CHARACTER SET utf8 COLLATE utf8_croatian_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) CHARACTER SET utf8 COLLATE utf8_croatian_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(500) CHARACTER SET utf8 COLLATE utf8_croatian_ci NULL DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`prompt_id`) USING BTREE,
  INDEX `idx_prompt_name`(`prompt_name`(64) ASC) USING BTREE,
  INDEX `idx_prompt_type`(`prompt_type` ASC, `status` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 4 CHARACTER SET = utf8 COLLATE = utf8_croatian_ci COMMENT = 'AI提示词表' ROW_FORMAT = Dynamic;

