DROP TABLE IF EXISTS `yg_ai_skill`;
CREATE TABLE `yg_ai_skill`  (
  `skill_id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '技能主键',
  `skill_name` varchar(100) CHARACTER SET utf8 COLLATE utf8_croatian_ci NOT NULL COMMENT '技能名称',
  `skill_code` varchar(100) CHARACTER SET utf8 COLLATE utf8_croatian_ci NOT NULL COMMENT '技能标识（唯一）',
  `category` varchar(50) CHARACTER SET utf8 COLLATE utf8_croatian_ci NULL DEFAULT '' COMMENT '技能分类',
  `description` varchar(500) CHARACTER SET utf8 COLLATE utf8_croatian_ci NULL DEFAULT '' COMMENT '技能说明',
  `content` longtext CHARACTER SET utf8 COLLATE utf8_croatian_ci NULL COMMENT '技能内容（提示词/脚本）',
  `status` char(1) CHARACTER SET utf8 COLLATE utf8_croatian_ci NULL DEFAULT '0' COMMENT '状态（0正常 1停用）',
  `del_flag` char(1) CHARACTER SET utf8 COLLATE utf8_croatian_ci NULL DEFAULT '0' COMMENT '删除标志（0代表存在 2代表删除）',
  `create_by` varchar(64) CHARACTER SET utf8 COLLATE utf8_croatian_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) CHARACTER SET utf8 COLLATE utf8_croatian_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(500) CHARACTER SET utf8 COLLATE utf8_croatian_ci NULL DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`skill_id`) USING BTREE,
  UNIQUE INDEX `uk_skill_code`(`skill_code` ASC) USING BTREE,
  INDEX `idx_skill_name`(`skill_name`(64) ASC) USING BTREE,
  INDEX `idx_skill_status`(`status` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_croatian_ci COMMENT = 'AI技能表' ROW_FORMAT = Dynamic;

