-- ----------------------------
-- Table structure for yg_amazon_ads_daily
-- ----------------------------
DROP TABLE IF EXISTS `yg_amazon_ads_daily`;
CREATE TABLE `yg_amazon_ads_daily`  (
  `daily_id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键',
  `report_date` date NOT NULL COMMENT '报告日期',
  `profile_id` varchar(64) CHARACTER SET utf8 COLLATE utf8_croatian_ci NULL DEFAULT '' COMMENT '广告档案/店铺标识(可选)',
  `campaign_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_croatian_ci NOT NULL COMMENT '广告活动名称',
  `impressions` bigint(20) NULL DEFAULT 0 COMMENT '曝光量',
  `clicks` bigint(20) NULL DEFAULT 0 COMMENT '点击量',
  `spend` decimal(12, 2) NULL DEFAULT 0.00 COMMENT '花费',
  `sales` decimal(12, 2) NULL DEFAULT 0.00 COMMENT '销售额',
  `orders` int(11) NULL DEFAULT 0 COMMENT '订单数',
  `create_by` varchar(64) CHARACTER SET utf8 COLLATE utf8_croatian_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) CHARACTER SET utf8 COLLATE utf8_croatian_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(500) CHARACTER SET utf8 COLLATE utf8_croatian_ci NULL DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`daily_id`) USING BTREE,
  UNIQUE INDEX `uk_date_profile_campaign`(`report_date` ASC, `profile_id` ASC, `campaign_name`(100) ASC) USING BTREE,
  INDEX `idx_campaign_date`(`campaign_name`(100) ASC, `report_date` ASC) USING BTREE,
  INDEX `idx_profile_date`(`profile_id` ASC, `report_date` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 43 CHARACTER SET = utf8 COLLATE = utf8_croatian_ci COMMENT = '亚马逊广告活动日报表' ROW_FORMAT = Dynamic;

