-- ----------------------------
-- Table structure for yg_card_info
-- ----------------------------
DROP TABLE IF EXISTS `yg_card_info`;
CREATE TABLE `yg_card_info`  (
  `card_id` bigint(20) NOT NULL COMMENT '卡片密码(id)',
  `cid` int(11) NULL DEFAULT NULL COMMENT '官方数据库标识(cid)',
  `cn_name` varchar(200) CHARACTER SET utf8 COLLATE utf8_croatian_ci NULL DEFAULT '' COMMENT '中文名称(YGOPro译名)',
  `sc_name` varchar(200) CHARACTER SET utf8 COLLATE utf8_croatian_ci NULL DEFAULT '' COMMENT '官方简体中文名称',
  `md_name` varchar(200) CHARACTER SET utf8 COLLATE utf8_croatian_ci NULL DEFAULT '' COMMENT 'Master Duel中文名称',
  `jp_name` varchar(200) CHARACTER SET utf8 COLLATE utf8_croatian_ci NULL DEFAULT '' COMMENT '官方日文名称',
  `jp_ruby` varchar(200) CHARACTER SET utf8 COLLATE utf8_croatian_ci NULL DEFAULT '' COMMENT '日文假名注音',
  `en_name` varchar(200) CHARACTER SET utf8 COLLATE utf8_croatian_ci NULL DEFAULT '' COMMENT '官方英文名称',
  `ot` int(11) NULL DEFAULT 0 COMMENT '可用环境位掩码(1:OCG 2:TCG 4:动画 8: illegal 16:视频 32:非法 64:仅OCG独有 128:仅TCG独有 等)',
  `setcode` bigint(20) UNSIGNED NULL DEFAULT 0 COMMENT '卡组系列code位掩码(64bit,关联yg_card_set)',
  `type` int(11) NULL DEFAULT 0 COMMENT '卡片类型位掩码(1:怪兽 2:魔法 4:陷阱 16:通常 32:效果 ...)',
  `card_kind` tinyint(2) NULL DEFAULT 1 COMMENT '卡片大类(1:怪兽 2:魔法 3:陷阱,由type解析)',
  `attribute` int(11) NULL DEFAULT 0 COMMENT '属性位掩码(1:地 2:水 4:炎 8:风 16:光 32:暗 64:神)',
  `race` int(11) NULL DEFAULT 0 COMMENT '种族位掩码(龙/战士/魔法使者等)',
  `atk` int(11) NULL DEFAULT -2 COMMENT '攻击力(-2:?)',
  `def` int(11) NULL DEFAULT -2 COMMENT '防御力(连接怪兽该字段存link_marker位掩码)',
  `level_raw` int(11) NULL DEFAULT 0 COMMENT '等级原始值(灵摆卡高16位含刻度)',
  `card_level` tinyint(4) NULL DEFAULT 0 COMMENT '等级/阶级(Rank<<8解析)',
  `lscale` tinyint(4) NULL DEFAULT NULL COMMENT '灵摆左刻度(非灵摆为NULL)',
  `rscale` tinyint(4) NULL DEFAULT NULL COMMENT '灵摆右刻度(非灵摆为NULL)',
  `link_marker` int(11) NULL DEFAULT NULL COMMENT '连接标记位掩码(非连接怪兽为NULL)',
  `types_desc` varchar(500) CHARACTER SET utf8 COLLATE utf8_croatian_ci NULL DEFAULT '' COMMENT '类型描述文本(text.types)',
  `effect_desc` text CHARACTER SET utf8 COLLATE utf8_croatian_ci NULL COMMENT '效果文本(text.desc)',
  `pendulum_desc` text CHARACTER SET utf8 COLLATE utf8_croatian_ci NULL COMMENT '灵摆效果文本(text.pdesc)',
  `image_url` varchar(200) CHARACTER SET utf8 COLLATE utf8_croatian_ci NULL DEFAULT '' COMMENT '卡图地址(CDN相对路径,前端拼接!half等参数)',
  `sync_source` tinyint(2) NULL DEFAULT 1 COMMENT '同步来源(1:全量导入 2:按需补录)',
  `sync_time` datetime NULL DEFAULT NULL COMMENT '最后同步时间',
  `status` char(1) CHARACTER SET utf8 COLLATE utf8_croatian_ci NULL DEFAULT '0' COMMENT '状态（0正常 1停用）',
  `del_flag` char(1) CHARACTER SET utf8 COLLATE utf8_croatian_ci NULL DEFAULT '0' COMMENT '删除标志（0代表存在 2代表删除）',
  `create_by` varchar(64) CHARACTER SET utf8 COLLATE utf8_croatian_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) CHARACTER SET utf8 COLLATE utf8_croatian_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(500) CHARACTER SET utf8 COLLATE utf8_croatian_ci NULL DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`card_id`) USING BTREE,
  UNIQUE INDEX `uk_cid`(`cid` ASC) USING BTREE,
  INDEX `idx_cn_name`(`cn_name`(64) ASC) USING BTREE,
  INDEX `idx_en_name`(`en_name`(64) ASC) USING BTREE,
  INDEX `idx_kind_attr`(`card_kind` ASC, `attribute` ASC) USING BTREE,
  INDEX `idx_level`(`card_level` ASC) USING BTREE,
  INDEX `idx_sync_time`(`sync_time` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8 COLLATE = utf8_croatian_ci COMMENT = '游戏王卡片信息表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of yg_card_info
-- ----------------------------

-- ----------------------------
-- Table structure for yg_card_set
-- ----------------------------
DROP TABLE IF EXISTS `yg_card_set`;
CREATE TABLE `yg_card_set`  (
  `set_id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '系列主键',
  `set_code` varchar(20) CHARACTER SET utf8 COLLATE utf8_croatian_ci NOT NULL COMMENT '系列code(十六进制字符串,如0x57)',
  `set_value` bigint(20) UNSIGNED NULL DEFAULT 0 COMMENT '系列code数值(用于与卡片setcode按位匹配)',
  `cn_name` varchar(100) CHARACTER SET utf8 COLLATE utf8_croatian_ci NULL DEFAULT '' COMMENT '系列中文名',
  `jp_name` varchar(100) CHARACTER SET utf8 COLLATE utf8_croatian_ci NULL DEFAULT '' COMMENT '系列日文名',
  `en_name` varchar(100) CHARACTER SET utf8 COLLATE utf8_croatian_ci NULL DEFAULT '' COMMENT '系列英文名',
  `status` char(1) CHARACTER SET utf8 COLLATE utf8_croatian_ci NULL DEFAULT '0' COMMENT '状态（0正常 1停用）',
  `create_by` varchar(64) CHARACTER SET utf8 COLLATE utf8_croatian_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) CHARACTER SET utf8 COLLATE utf8_croatian_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(500) CHARACTER SET utf8 COLLATE utf8_croatian_ci NULL DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`set_id`) USING BTREE,
  UNIQUE INDEX `uk_set_code`(`set_code` ASC) USING BTREE,
  INDEX `idx_set_cn_name`(`cn_name` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 600 CHARACTER SET = utf8 COLLATE = utf8_croatian_ci COMMENT = '卡组系列表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of yg_card_set
-- ----------------------------

-- ----------------------------
-- Table structure for yg_facebook_ads_daily
-- ----------------------------
DROP TABLE IF EXISTS `yg_facebook_ads_daily`;
CREATE TABLE `yg_facebook_ads_daily`  (
  `daily_id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键',
  `report_date` date NOT NULL COMMENT '报告日期',
  `account_id` varchar(64) CHARACTER SET utf8 COLLATE utf8_croatian_ci NULL DEFAULT '' COMMENT '广告账户(标识,可选)',
  `campaign_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_croatian_ci NOT NULL COMMENT '广告活动名称',
  `impressions` bigint(20) NULL DEFAULT 0 COMMENT '曝光量',
  `clicks` bigint(20) NULL DEFAULT 0 COMMENT '点击量',
  `spend` decimal(12, 2) NULL DEFAULT 0.00 COMMENT '花费',
  `sales` decimal(12, 2) NULL DEFAULT 0.00 COMMENT '销售额',
  `orders` int(11) NULL DEFAULT 0 COMMENT '订单数',
  `create_by` varchar(64) CHARACTER SET utf8 COLLATE utf8_croatian_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) CHARACTER SET utf8 COLLATE utf8_croatian_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(500) CHARACTER SET utf8 COLLATE utf8_croatian_ci NULL DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`daily_id`) USING BTREE,
  UNIQUE INDEX `uk_date_account_campaign`(`report_date` ASC, `account_id` ASC, `campaign_name`(100) ASC) USING BTREE,
  INDEX `idx_campaign_date`(`campaign_name`(100) ASC, `report_date` ASC) USING BTREE,
  INDEX `idx_account_date`(`account_id` ASC, `report_date` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 43 CHARACTER SET = utf8 COLLATE = utf8_croatian_ci COMMENT = 'Facebook广告活动日报表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of yg_facebook_ads_daily
-- ----------------------------

-- ----------------------------
-- Table structure for yg_kb_chat_log
-- ----------------------------
DROP TABLE IF EXISTS `yg_kb_chat_log`;
CREATE TABLE `yg_kb_chat_log`  (
  `log_id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '日志主键',
  `kb_id` bigint(20) NOT NULL COMMENT '知识库ID',
  `question` varchar(2000) CHARACTER SET utf8 COLLATE utf8_croatian_ci NOT NULL COMMENT '问题',
  `answer` mediumtext CHARACTER SET utf8 COLLATE utf8_croatian_ci NULL COMMENT '回答',
  `source_json` text CHARACTER SET utf8 COLLATE utf8_croatian_ci NULL COMMENT '引用来源(JSON)',
  `cost_ms` bigint(20) NULL DEFAULT 0 COMMENT '耗时(毫秒)',
  `create_by` varchar(64) CHARACTER SET utf8 COLLATE utf8_croatian_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  PRIMARY KEY (`log_id`) USING BTREE,
  INDEX `idx_log_kb_id`(`kb_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 5 CHARACTER SET = utf8 COLLATE = utf8_croatian_ci COMMENT = '知识库问答日志表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of yg_kb_chat_log
-- ----------------------------

-- ----------------------------
-- Table structure for yg_kb_custom_api
-- ----------------------------
DROP TABLE IF EXISTS `yg_kb_custom_api`;
CREATE TABLE `yg_kb_custom_api`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键',
  `name` varchar(100) CHARACTER SET utf8 COLLATE utf8_croatian_ci NOT NULL COMMENT '名称(下拉展示用)',
  `base_url` varchar(200) CHARACTER SET utf8 COLLATE utf8_croatian_ci NULL DEFAULT '' COMMENT '服务地址(OpenAI兼容)',
  `api_key` varchar(200) CHARACTER SET utf8 COLLATE utf8_croatian_ci NULL DEFAULT '' COMMENT 'API Key',
  `chat_model` varchar(100) CHARACTER SET utf8 COLLATE utf8_croatian_ci NULL DEFAULT '' COMMENT '对话模型',
  `chat_temperature` decimal(3, 2) NULL DEFAULT 0.30 COMMENT '温度',
  `embedding_model` varchar(100) CHARACTER SET utf8 COLLATE utf8_croatian_ci NULL DEFAULT '' COMMENT '向量化模型',
  `embedding_dim` int(11) NULL DEFAULT 1024 COMMENT '向量维度',
  `timeout_seconds` int(11) NULL DEFAULT 60 COMMENT '超时秒数',
  `create_by` varchar(64) CHARACTER SET utf8 COLLATE utf8_croatian_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) CHARACTER SET utf8 COLLATE utf8_croatian_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 3 CHARACTER SET = utf8 COLLATE = utf8_croatian_ci COMMENT = '知识库自定义API配置表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of yg_kb_custom_api
-- ----------------------------

-- ----------------------------
-- Table structure for yg_kb_document
-- ----------------------------
DROP TABLE IF EXISTS `yg_kb_document`;
CREATE TABLE `yg_kb_document`  (
  `doc_id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '文档主键',
  `kb_id` bigint(20) NOT NULL COMMENT '所属知识库ID',
  `file_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_croatian_ci NOT NULL COMMENT '原始文件名',
  `file_path` varchar(500) CHARACTER SET utf8 COLLATE utf8_croatian_ci NOT NULL COMMENT '存储路径',
  `file_type` varchar(10) CHARACTER SET utf8 COLLATE utf8_croatian_ci NULL DEFAULT '' COMMENT '文件类型(txt/md/pdf/docx)',
  `file_size` bigint(20) NULL DEFAULT 0 COMMENT '文件大小(字节)',
  `chunk_count` int(11) NULL DEFAULT 0 COMMENT '分块数',
  `index_status` char(1) CHARACTER SET utf8 COLLATE utf8_croatian_ci NULL DEFAULT '0' COMMENT '索引状态（0待索引 1索引中 2成功 3失败）',
  `error_msg` varchar(1000) CHARACTER SET utf8 COLLATE utf8_croatian_ci NULL DEFAULT NULL COMMENT '失败原因',
  `del_flag` char(1) CHARACTER SET utf8 COLLATE utf8_croatian_ci NULL DEFAULT '0' COMMENT '删除标志（0代表存在 2代表删除）',
  `create_by` varchar(64) CHARACTER SET utf8 COLLATE utf8_croatian_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) CHARACTER SET utf8 COLLATE utf8_croatian_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(500) CHARACTER SET utf8 COLLATE utf8_croatian_ci NULL DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`doc_id`) USING BTREE,
  INDEX `idx_doc_kb_id`(`kb_id` ASC, `del_flag` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 5 CHARACTER SET = utf8 COLLATE = utf8_croatian_ci COMMENT = '知识库文档表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of yg_kb_document
-- ----------------------------

-- ----------------------------
-- Table structure for yg_kb_model_config
-- ----------------------------
DROP TABLE IF EXISTS `yg_kb_model_config`;
CREATE TABLE `yg_kb_model_config`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键',
  `provider` varchar(20) CHARACTER SET utf8 COLLATE utf8_croatian_ci NOT NULL DEFAULT 'ollama' COMMENT '模型提供方(ollama/openai/custom)，兼容旧数据',
  `chat_provider` varchar(20) CHARACTER SET utf8 COLLATE utf8_croatian_ci NOT NULL DEFAULT 'ollama' COMMENT '对话模型提供方(ollama/openai/custom)',
  `embedding_provider` varchar(20) CHARACTER SET utf8 COLLATE utf8_croatian_ci NOT NULL DEFAULT 'ollama' COMMENT '向量化模型提供方(ollama/openai/custom)',
  `ollama_base_url` varchar(200) CHARACTER SET utf8 COLLATE utf8_croatian_ci NULL DEFAULT 'http://localhost:11434' COMMENT 'Ollama服务地址',
  `ollama_chat_model` varchar(100) CHARACTER SET utf8 COLLATE utf8_croatian_ci NULL DEFAULT 'qwen2.5:7b' COMMENT 'Ollama对话模型',
  `ollama_chat_temperature` decimal(3, 2) NULL DEFAULT 0.30 COMMENT 'Ollama温度',
  `ollama_embedding_model` varchar(100) CHARACTER SET utf8 COLLATE utf8_croatian_ci NULL DEFAULT 'bge-m3' COMMENT 'Ollama向量化模型',
  `ollama_embedding_dim` int(11) NULL DEFAULT 1024 COMMENT 'Ollama向量维度',
  `ollama_timeout_seconds` int(11) NULL DEFAULT 300 COMMENT 'Ollama超时秒数',
  `openai_base_url` varchar(200) CHARACTER SET utf8 COLLATE utf8_croatian_ci NULL DEFAULT 'http://localhost:8080/v1' COMMENT 'llama-server/OpenAI兼容地址',
  `openai_api_key` varchar(100) CHARACTER SET utf8 COLLATE utf8_croatian_ci NULL DEFAULT 'none' COMMENT 'API Key',
  `openai_chat_model` varchar(100) CHARACTER SET utf8 COLLATE utf8_croatian_ci NULL DEFAULT 'qwen2.5-7b-instruct-q8_0' COMMENT 'OpenAI兼容对话模型',
  `openai_chat_temperature` decimal(3, 2) NULL DEFAULT 0.30 COMMENT 'OpenAI兼容温度',
  `openai_embedding_model` varchar(100) CHARACTER SET utf8 COLLATE utf8_croatian_ci NULL DEFAULT 'bge-m3' COMMENT 'OpenAI兼容向量化模型',
  `openai_embedding_dim` int(11) NULL DEFAULT 1024 COMMENT 'OpenAI兼容向量维度',
  `openai_timeout_seconds` int(11) NULL DEFAULT 300 COMMENT 'OpenAI兼容超时秒数',
  `custom_chat_api_id` bigint(20) NULL DEFAULT NULL COMMENT '对话用自定义API ID(yg_kb_custom_api.id)',
  `custom_embedding_api_id` bigint(20) NULL DEFAULT NULL COMMENT '向量化用自定义API ID(yg_kb_custom_api.id)',
  `chunk_strategy` varchar(20) CHARACTER SET utf8 COLLATE utf8_croatian_ci NULL DEFAULT 'recursive' COMMENT '分块策略(recursive/paragraph/sentence/separator/markdown)',
  `chunk_separator` varchar(100) CHARACTER SET utf8 COLLATE utf8_croatian_ci NULL DEFAULT '' COMMENT '自定义分隔符(strategy=separator时生效)',
  `chunk_max_size` int(11) NULL DEFAULT 500 COMMENT '分块最大长度(字符)',
  `chunk_overlap` int(11) NULL DEFAULT 100 COMMENT '分块重叠长度(字符)',
  `retrieval_max_results` int(11) NULL DEFAULT 4 COMMENT '检索返回片段数',
  `retrieval_min_score` decimal(4, 3) NULL DEFAULT 0.300 COMMENT '检索最低相似度',
  `update_by` varchar(64) CHARACTER SET utf8 COLLATE utf8_croatian_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2 CHARACTER SET = utf8 COLLATE = utf8_croatian_ci COMMENT = '知识库模型配置表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of yg_kb_model_config
-- ----------------------------

-- ----------------------------
-- Table structure for yg_knowledge_base
-- ----------------------------
DROP TABLE IF EXISTS `yg_knowledge_base`;
CREATE TABLE `yg_knowledge_base`  (
  `kb_id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '知识库主键',
  `kb_name` varchar(100) CHARACTER SET utf8 COLLATE utf8_croatian_ci NOT NULL COMMENT '知识库名称',
  `description` varchar(500) CHARACTER SET utf8 COLLATE utf8_croatian_ci NULL DEFAULT '' COMMENT '描述',
  `embedding_model` varchar(100) CHARACTER SET utf8 COLLATE utf8_croatian_ci NULL DEFAULT '' COMMENT '向量化模型(建库时固化)',
  `embedding_dim` int(11) NULL DEFAULT 0 COMMENT '向量维度',
  `doc_count` int(11) NULL DEFAULT 0 COMMENT '文档数',
  `chunk_count` int(11) NULL DEFAULT 0 COMMENT '分块数',
  `status` char(1) CHARACTER SET utf8 COLLATE utf8_croatian_ci NULL DEFAULT '0' COMMENT '状态（0正常 1停用）',
  `del_flag` char(1) CHARACTER SET utf8 COLLATE utf8_croatian_ci NULL DEFAULT '0' COMMENT '删除标志（0代表存在 2代表删除）',
  `create_by` varchar(64) CHARACTER SET utf8 COLLATE utf8_croatian_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) CHARACTER SET utf8 COLLATE utf8_croatian_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(500) CHARACTER SET utf8 COLLATE utf8_croatian_ci NULL DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`kb_id`) USING BTREE,
  INDEX `idx_kb_name`(`kb_name`(64) ASC) USING BTREE,
  INDEX `idx_kb_status`(`status` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 4 CHARACTER SET = utf8 COLLATE = utf8_croatian_ci COMMENT = '知识库表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of yg_knowledge_base
-- ----------------------------

-- ----------------------------
-- Table structure for yg_limit_list
-- ----------------------------
DROP TABLE IF EXISTS `yg_limit_list`;
CREATE TABLE `yg_limit_list`  (
  `limit_id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键',
  `card_id` bigint(20) NOT NULL COMMENT '卡片密码(id)',
  `ot_type` varchar(10) CHARACTER SET utf8 COLLATE utf8_croatian_ci NOT NULL COMMENT '适用环境(ocg/tcg/sc)',
  `limit_type` tinyint(2) NOT NULL DEFAULT 0 COMMENT '限制类型(0:无限制 1:限制 2:准限制 3:禁止)',
  `effective_date` date NOT NULL COMMENT '生效日期',
  `is_current` char(1) CHARACTER SET utf8 COLLATE utf8_croatian_ci NULL DEFAULT '1' COMMENT '是否当前卡表（1是 0历史）',
  `create_by` varchar(64) CHARACTER SET utf8 COLLATE utf8_croatian_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) CHARACTER SET utf8 COLLATE utf8_croatian_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(500) CHARACTER SET utf8 COLLATE utf8_croatian_ci NULL DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`limit_id`) USING BTREE,
  UNIQUE INDEX `uk_card_ot_date`(`card_id` ASC, `ot_type` ASC, `effective_date` ASC) USING BTREE,
  INDEX `idx_current`(`ot_type` ASC, `is_current` ASC, `limit_type` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 527 CHARACTER SET = utf8 COLLATE = utf8_croatian_ci COMMENT = '禁限卡表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of yg_limit_list
-- ----------------------------

-- ----------------------------
-- Table structure for yg_media
-- ----------------------------
DROP TABLE IF EXISTS `yg_media`;
CREATE TABLE `yg_media`  (
  `media_id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '素材主键',
  `media_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_croatian_ci NOT NULL COMMENT '素材名称（可重命名）',
  `original_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_croatian_ci NULL DEFAULT '' COMMENT '上传时原始文件名',
  `media_type` tinyint(2) NOT NULL DEFAULT 1 COMMENT '素材类型(1:图片 2:视频)',
  `file_url` varchar(500) CHARACTER SET utf8 COLLATE utf8_croatian_ci NOT NULL COMMENT '文件地址(/profile/...)',
  `file_size` bigint(20) NULL DEFAULT 0 COMMENT '文件大小(字节)',
  `ext` varchar(20) CHARACTER SET utf8 COLLATE utf8_croatian_ci NULL DEFAULT '' COMMENT '扩展名(jpg/png/mp4等)',
  `category` varchar(100) CHARACTER SET utf8 COLLATE utf8_croatian_ci NULL DEFAULT '' COMMENT '分类/标签',
  `del_flag` char(1) CHARACTER SET utf8 COLLATE utf8_croatian_ci NULL DEFAULT '0' COMMENT '删除标志（0代表存在 2代表删除）',
  `create_by` varchar(64) CHARACTER SET utf8 COLLATE utf8_croatian_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) CHARACTER SET utf8 COLLATE utf8_croatian_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(500) CHARACTER SET utf8 COLLATE utf8_croatian_ci NULL DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`media_id`) USING BTREE,
  INDEX `idx_media_name`(`media_name`(64) ASC) USING BTREE,
  INDEX `idx_media_type`(`media_type` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2 CHARACTER SET = utf8 COLLATE = utf8_croatian_ci COMMENT = 'AI素材库表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of yg_media
-- ----------------------------

-- ----------------------------
-- Table structure for yg_shop_store
-- ----------------------------
DROP TABLE IF EXISTS `yg_shop_store`;
CREATE TABLE `yg_shop_store`  (
  `store_id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '店铺主键',
  `store_name` varchar(100) CHARACTER SET utf8 COLLATE utf8_croatian_ci NOT NULL COMMENT '店铺名称',
  `store_url` varchar(255) CHARACTER SET utf8 COLLATE utf8_croatian_ci NOT NULL COMMENT '店铺地址(如 https://shop.example.com)',
  `consumer_key` varchar(255) CHARACTER SET utf8 COLLATE utf8_croatian_ci NULL DEFAULT '' COMMENT 'WooCommerce Consumer Key',
  `consumer_secret` varchar(255) CHARACTER SET utf8 COLLATE utf8_croatian_ci NULL DEFAULT '' COMMENT 'WooCommerce Consumer Secret',
  `status` char(1) CHARACTER SET utf8 COLLATE utf8_croatian_ci NULL DEFAULT '0' COMMENT '状态（0正常 1停用）',
  `sort` int(11) NULL DEFAULT 0 COMMENT '显示排序',
  `last_sync_time` datetime NULL DEFAULT NULL COMMENT '最近同步时间',
  `create_by` varchar(64) CHARACTER SET utf8 COLLATE utf8_croatian_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) CHARACTER SET utf8 COLLATE utf8_croatian_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(500) CHARACTER SET utf8 COLLATE utf8_croatian_ci NULL DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`store_id`) USING BTREE,
  UNIQUE INDEX `uk_store_url`(`store_url` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 3 CHARACTER SET = utf8 COLLATE = utf8_croatian_ci COMMENT = '店铺设置表' ROW_FORMAT = Dynamic;

