-- ----------------------------
-- Table structure for yg_shop_webhook
-- ----------------------------
DROP TABLE IF EXISTS `yg_shop_webhook`;
CREATE TABLE `yg_shop_webhook`  (
  `webhook_id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键',
  `store_id` bigint(20) NOT NULL COMMENT '店铺ID',
  `woo_webhook_id` bigint(20) NOT NULL COMMENT 'WooCommerce Webhook ID',
  `name` varchar(200) CHARACTER SET utf8 COLLATE utf8_croatian_ci NOT NULL COMMENT 'Webhook名称',
  `topic` varchar(64) CHARACTER SET utf8 COLLATE utf8_croatian_ci NOT NULL COMMENT '主题(order.created/order.updated等)',
  `delivery_url` varchar(500) CHARACTER SET utf8 COLLATE utf8_croatian_ci NOT NULL COMMENT '回调地址',
  `secret` varchar(100) CHARACTER SET utf8 COLLATE utf8_croatian_ci NULL DEFAULT '' COMMENT '密钥(用于HMAC-SHA256签名校验)',
  `status` char(1) CHARACTER SET utf8 COLLATE utf8_croatian_ci NULL DEFAULT '0' COMMENT '状态（0启用 1停用）',
  `last_delivery_time` datetime NULL DEFAULT NULL COMMENT '最近推送时间',
  `last_delivery_status` char(1) CHARACTER SET utf8 COLLATE utf8_croatian_ci NULL DEFAULT NULL COMMENT '最近推送结果（0成功 1失败）',
  `create_by` varchar(64) CHARACTER SET utf8 COLLATE utf8_croatian_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) CHARACTER SET utf8 COLLATE utf8_croatian_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(500) CHARACTER SET utf8 COLLATE utf8_croatian_ci NULL DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`webhook_id`) USING BTREE,
  UNIQUE INDEX `uk_store_webhook`(`store_id` ASC, `woo_webhook_id` ASC) USING BTREE,
  INDEX `idx_webhook_topic`(`topic` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_croatian_ci COMMENT = '店铺Webhook表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of yg_shop_webhook
-- ----------------------------

-- ----------------------------
-- Table structure for yg_shop_woo_order
-- ----------------------------
DROP TABLE IF EXISTS `yg_shop_woo_order`;
CREATE TABLE `yg_shop_woo_order`  (
  `order_id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键',
  `store_id` bigint(20) NOT NULL COMMENT '店铺ID',
  `woo_order_id` bigint(20) NOT NULL COMMENT 'WooCommerce订单ID',
  `order_number` varchar(64) CHARACTER SET utf8 COLLATE utf8_croatian_ci NULL DEFAULT '' COMMENT '订单号',
  `status` varchar(32) CHARACTER SET utf8 COLLATE utf8_croatian_ci NULL DEFAULT '' COMMENT '订单状态(pending/processing/completed等)',
  `currency` varchar(10) CHARACTER SET utf8 COLLATE utf8_croatian_ci NULL DEFAULT '' COMMENT '币种',
  `total` decimal(12, 2) NULL DEFAULT 0.00 COMMENT '订单总额',
  `customer_name` varchar(200) CHARACTER SET utf8 COLLATE utf8_croatian_ci NULL DEFAULT '' COMMENT '客户姓名',
  `customer_email` varchar(200) CHARACTER SET utf8 COLLATE utf8_croatian_ci NULL DEFAULT '' COMMENT '客户邮箱',
  `payment_method` varchar(100) CHARACTER SET utf8 COLLATE utf8_croatian_ci NULL DEFAULT '' COMMENT '支付方式',
  `item_count` int(11) NULL DEFAULT 0 COMMENT '商品件数',
  `items_summary` varchar(1000) CHARACTER SET utf8 COLLATE utf8_croatian_ci NULL DEFAULT '' COMMENT '商品摘要',
  `date_created` datetime NULL DEFAULT NULL COMMENT '下单时间',
  `date_paid` datetime NULL DEFAULT NULL COMMENT '支付时间',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`order_id`) USING BTREE,
  UNIQUE INDEX `uk_store_order`(`store_id` ASC, `woo_order_id` ASC) USING BTREE,
  INDEX `idx_order_status`(`status` ASC) USING BTREE,
  INDEX `idx_order_created`(`date_created` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 3 CHARACTER SET = utf8 COLLATE = utf8_croatian_ci COMMENT = 'WooCommerce订单表' ROW_FORMAT = Dynamic;

