-- ----------------------------
-- Table structure for yg_shop_woo_post
-- ----------------------------
DROP TABLE IF EXISTS `yg_shop_woo_post`;
CREATE TABLE `yg_shop_woo_post`  (
  `post_id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键',
  `store_id` bigint(20) NOT NULL COMMENT '店铺ID',
  `woo_post_id` bigint(20) NOT NULL COMMENT 'WordPress文章ID',
  `title` varchar(500) CHARACTER SET utf8 COLLATE utf8_croatian_ci NULL DEFAULT '' COMMENT '文章标题',
  `slug` varchar(255) CHARACTER SET utf8 COLLATE utf8_croatian_ci NULL DEFAULT '' COMMENT '文章别名',
  `status` varchar(32) CHARACTER SET utf8 COLLATE utf8_croatian_ci NULL DEFAULT '' COMMENT '文章状态(publish/draft等)',
  `excerpt` varchar(1000) CHARACTER SET utf8 COLLATE utf8_croatian_ci NULL DEFAULT '' COMMENT '摘要(纯文本)',
  `content` mediumtext CHARACTER SET utf8 COLLATE utf8_croatian_ci NULL COMMENT '正文(纯文本)',
  `link` varchar(500) CHARACTER SET utf8 COLLATE utf8_croatian_ci NULL DEFAULT '' COMMENT '文章链接',
  `date_created` datetime NULL DEFAULT NULL COMMENT '发布时间',
  `date_modified` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `create_time` datetime NULL DEFAULT NULL COMMENT '同步时间',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`post_id`) USING BTREE,
  UNIQUE INDEX `uk_store_post`(`store_id` ASC, `woo_post_id` ASC) USING BTREE,
  INDEX `idx_post_status`(`status` ASC) USING BTREE,
  INDEX `idx_post_created`(`date_created` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2 CHARACTER SET = utf8 COLLATE = utf8_croatian_ci COMMENT = 'WooCommerce文章表' ROW_FORMAT = Dynamic;

