-- ----------------------------
-- Table structure for yg_shop_woo_product
-- ----------------------------
DROP TABLE IF EXISTS `yg_shop_woo_product`;
CREATE TABLE `yg_shop_woo_product`  (
  `product_id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键',
  `store_id` bigint(20) NOT NULL COMMENT '店铺ID',
  `woo_product_id` bigint(20) NOT NULL COMMENT 'WooCommerce商品ID',
  `name` varchar(500) CHARACTER SET utf8 COLLATE utf8_croatian_ci NULL DEFAULT '' COMMENT '商品名称',
  `sku` varchar(200) CHARACTER SET utf8 COLLATE utf8_croatian_ci NULL DEFAULT '' COMMENT 'SKU',
  `type` varchar(32) CHARACTER SET utf8 COLLATE utf8_croatian_ci NULL DEFAULT '' COMMENT '商品类型(simple/variable等)',
  `status` varchar(32) CHARACTER SET utf8 COLLATE utf8_croatian_ci NULL DEFAULT '' COMMENT '商品状态(publish/draft等)',
  `price` decimal(12, 2) NULL DEFAULT 0.00 COMMENT '现价',
  `regular_price` decimal(12, 2) NULL DEFAULT 0.00 COMMENT '原价',
  `sale_price` decimal(12, 2) NULL DEFAULT 0.00 COMMENT '促销价',
  `stock_quantity` int(11) NULL DEFAULT NULL COMMENT '库存数量',
  `stock_status` varchar(32) CHARACTER SET utf8 COLLATE utf8_croatian_ci NULL DEFAULT '' COMMENT '库存状态(instock/outofstock)',
  `categories` varchar(500) CHARACTER SET utf8 COLLATE utf8_croatian_ci NULL DEFAULT '' COMMENT '商品分类(斜杠分隔)',
  `image_url` varchar(500) CHARACTER SET utf8 COLLATE utf8_croatian_ci NULL DEFAULT '' COMMENT '主图地址',
  `permalink` varchar(500) CHARACTER SET utf8 COLLATE utf8_croatian_ci NULL DEFAULT '' COMMENT '商品链接',
  `date_created` datetime NULL DEFAULT NULL COMMENT '创建时间(店铺)',
  `date_modified` datetime NULL DEFAULT NULL COMMENT '更新时间(店铺)',
  `create_time` datetime NULL DEFAULT NULL COMMENT '同步时间',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`product_id`) USING BTREE,
  UNIQUE INDEX `uk_store_product`(`store_id` ASC, `woo_product_id` ASC) USING BTREE,
  INDEX `idx_product_status`(`status` ASC) USING BTREE,
  INDEX `idx_product_sku`(`sku` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 38 CHARACTER SET = utf8 COLLATE = utf8_croatian_ci COMMENT = 'WooCommerce商品表' ROW_FORMAT = Dynamic;

