-- ----------------------------
-- Table structure for yg_shopify_store_daily
-- ----------------------------
DROP TABLE IF EXISTS `yg_shopify_store_daily`;
CREATE TABLE `yg_shopify_store_daily`  (
  `daily_id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键',
  `report_date` date NOT NULL COMMENT '报告日期',
  `store_domain` varchar(128) CHARACTER SET utf8 COLLATE utf8_croatian_ci NULL DEFAULT '' COMMENT '店铺域名(标识,可选)',
  `channel` varchar(255) CHARACTER SET utf8 COLLATE utf8_croatian_ci NOT NULL COMMENT '销售渠道',
  `sessions` bigint(20) NULL DEFAULT 0 COMMENT '会话数(访客数)',
  `orders` int(11) NULL DEFAULT 0 COMMENT '订单数',
  `units_sold` int(11) NULL DEFAULT 0 COMMENT '售出件数',
  `revenue` decimal(12, 2) NULL DEFAULT 0.00 COMMENT '销售额',
  `create_by` varchar(64) CHARACTER SET utf8 COLLATE utf8_croatian_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) CHARACTER SET utf8 COLLATE utf8_croatian_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(500) CHARACTER SET utf8 COLLATE utf8_croatian_ci NULL DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`daily_id`) USING BTREE,
  UNIQUE INDEX `uk_date_store_channel`(`report_date` ASC, `store_domain` ASC, `channel`(100) ASC) USING BTREE,
  INDEX `idx_channel_date`(`channel`(100) ASC, `report_date` ASC) USING BTREE,
  INDEX `idx_store_date`(`store_domain` ASC, `report_date` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_croatian_ci COMMENT = 'Shopify店铺渠道日报表' ROW_FORMAT = Dynamic;

