-- ----------------------------
-- Table structure for yg_update_log
-- ----------------------------
DROP TABLE IF EXISTS `yg_update_log`;
CREATE TABLE `yg_update_log`  (
  `log_id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '日志主键',
  `version` varchar(50) CHARACTER SET utf8 COLLATE utf8_croatian_ci NOT NULL COMMENT '版本号',
  `content` text CHARACTER SET utf8 COLLATE utf8_croatian_ci NOT NULL COMMENT '更新内容',
  `status` char(1) CHARACTER SET utf8 COLLATE utf8_croatian_ci NULL DEFAULT '0' COMMENT '状态（0正常 1停用）',
  `del_flag` char(1) CHARACTER SET utf8 COLLATE utf8_croatian_ci NULL DEFAULT '0' COMMENT '删除标志（0代表存在 2代表删除）',
