INSERT INTO `yg_update_log` VALUES (1, 'V1.0.0', '1. 新增卡片图鉴浏览与搜索功能；\n2. 新增我的收藏；\n3. 修复若干已知问题。', '0', '0', 'admin', '2026-10-14 12:52:32', '', NULL, '首发版本');
INSERT INTO `yg_update_log` VALUES (2, 'V1.1.0', '1. 新增 AI 提示词模块；\n2. 新增卡包与决斗功能；\n3. 优化图片放大查看体验。', '0', '0', 'admin', '2026-10-14 12:52:32', '', NULL, '功能更新');
INSERT INTO `yg_update_log` VALUES (3, 'V1.2.0', '1. 新增\"数据管理\"目录；\n2. 新增亚马逊广告数据分析模块，支持广告活动日报导入、手动维护与图表分析。', '0', '0', 'admin', '2026-10-14 18:18:19', '', NULL, '亚马逊广告数据分析');
INSERT INTO `yg_update_log` VALUES (4, 'V1.3.0', '1. 新增\"工具使用\"模块；\n2. 支持维护常用网站名称与地址，提供表格/列表两种视图；\n3. 点击按钮可在新窗口打开对应网站。', '0', '0', 'admin', '2026-10-16 15:14:17', '', NULL, '工具使用');
INSERT INTO `yg_update_log` VALUES (5, 'V1.3.0', '1. 新增Facebook广告数据分析模块，支持广告活动日报导入、手动维护与图表分析。', '0', '0', 'admin', '2026-10-16 16:35:20', '', NULL, 'Facebook广告数据分析');
INSERT INTO `yg_update_log` VALUES (6, 'V1.3.0', '1. 新增\"工具使用\"模块；\n2. 支持维护常用网站名称与地址，提供表格/列表两种视图；\n3. 点击按钮可在新窗口打开对应网站。', '0', '0', 'admin', '2026-10-16 16:46:17', '', NULL, '工具使用');
INSERT INTO `yg_update_log` VALUES (7, 'V1.3.1', '1. 工具使用新增\"分类\"功能；\n2. 新增字典 yg_tool_category（开发工具/AI工具/电商平台/数据分析/官方资讯/其他）；\n3. 列表与宫格视图支持分类展示与筛选。', '0', '0', 'admin', '2026-10-16 16:46:17', '', NULL, '工具使用');
INSERT INTO `yg_update_log` VALUES (8, 'V1.4.0', '1. 新增Shopify数据分析模块，支持店铺渠道日报导入、手动维护与图表分析。', '0', '0', 'admin', '2026-10-16 16:57:47', '', NULL, 'Shopify数据分析');
INSERT INTO `yg_update_log` VALUES (9, 'V1.5.0', '1. 新增WooCommerce数据分析模块，支持店铺渠道日报导入、手动维护与图表分析。', '0', '0', 'admin', '2026-10-16 19:31:51', '', NULL, 'WooCommerce数据分析');
INSERT INTO `yg_update_log` VALUES (10, 'V1.6.0', '1. 新增店铺管理模块，支持多店铺设置、WooCommerce订单/商品/文章同步与查询。', '0', '0', 'admin', '2026-10-23 22:49:01', '', NULL, '店铺管理');
INSERT INTO `yg_update_log` VALUES (11, 'V1.7.0', '1. 新增Webhooks管理，支持店铺Webhook配置与接收回调自动更新订单/商品。', '0', '0', 'admin', '2026-10-23 23:40:33', '', NULL, 'Webhooks');
